export type AnatomySystem = 'skin' | 'skeleton' | 'joints' | 'muscles' | 'organs' | 'vessels' | 'nerves';
export type AnatomySex = 'male' | 'female' | 'both';
export type Vec3 = [number, number, number];

export interface UnifiedAnatomicalStructure {
  /** Stable ID, also the glTF node name in the GLB models */
  id: string;
  /** Human-readable English label */
  label: string;
  /** Body system */
  system: AnatomySystem;
  /** Clinical category (Cardiovascular, Musculoskeletal, etc.) */
  category: string;
  /** Suggested display color (hex) */
  color: string;
  /** Anchor position in the MALE model (metres, Y-up) */
  anchorMale?: Vec3;
  /** Anchor position in the FEMALE model (metres, Y-up) */
  anchorFemale?: Vec3;
  /** 'male' or 'female' if structure exists in only one body */
  sex?: AnatomySex;
  /** Source dataset */
  source: 'open-anatomy-3d' | 'bodyparts3d' | 'hubmap' | 'z-anatomy' | 'surgitrack';
  /** glTF node name (for raycasting selection) */
  meshKey?: string;
  /** FMA ID (if matched to BodyParts3D) */
  fmaId?: string;
  /** Japanese name (Kanji) from BodyParts3D */
  kanji?: string;
  /** Japanese name (Kana) from BodyParts3D */
  kana?: string;
  /** Whether this structure has a real 3D mesh in the GLB files */
  hasRealMesh: boolean;
}

