// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

export function getStructureById(id: string): UnifiedAnatomicalStructure | undefined {
  return UNIFIED_ANATOMICAL_CATALOG.find(s => s.id === id);
}

export function getStructuresBySystem(system: AnatomySystem): UnifiedAnatomicalStructure[] {
  return UNIFIED_ANATOMICAL_CATALOG.filter(s => s.system === system);
}

export function getStructuresByCategory(category: string): UnifiedAnatomicalStructure[] {
  return UNIFIED_ANATOMICAL_CATALOG.filter(s => s.category === category);
}

export function getStructuresBySex(sex: AnatomySex): UnifiedAnatomicalStructure[] {
  return UNIFIED_ANATOMICAL_CATALOG.filter(s => !s.sex || s.sex === sex);
}

export function searchStructures(query: string, lang: 'en' | 'ar' | 'de' | 'ja' = 'en'): UnifiedAnatomicalStructure[] {
  const q = query.toLowerCase().trim();
  if (!q) return [];
  return UNIFIED_ANATOMICAL_CATALOG.filter(s =>
    s.label.toLowerCase().includes(q) ||
    s.id.toLowerCase().includes(q) ||
    s.category.toLowerCase().includes(q) ||
    (s.kanji && s.kanji.includes(q)) ||
    (s.kana && s.kana.includes(q))
  );
}
